module carry_save_adder(input [3:0] a, b, c, output [4:0] sum);
  wire [3:0] s_temp, cout_temp;
  wire [2:0] co;

  // First stage: full adders for each bit
  full_adder fa0(a[0], b[0], c[0], s_temp[0], cout_temp[0]);
  full_adder fa1(a[1], b[1], c[1], s_temp[1], cout_temp[1]);
  full_adder fa2(a[2], b[2], c[2], s_temp[2], cout_temp[2]);
  full_adder fa3(a[3], b[3], c[3], s_temp[3], cout_temp[3]);

  // Second stage: ripple adder for sum and carry vectors
  full_adder fa4(s_temp[1], cout_temp[0], 1'b0, sum[1], co[0]);
  full_adder fa5(s_temp[2], cout_temp[1], co[0], sum[2], co[1]);
  full_adder fa6(s_temp[3], cout_temp[2], co[1], sum[3], co[2]);
  full_adder fa7(1'b0, cout_temp[3], co[2], sum[4], ); // no cout needed

  assign sum[0] = s_temp[0];
endmodule

