module master_slave_dff(input clk, d, output q);
  reg master, slave;

  // Master latch (negative level sensitive)
  always @(clk or d) begin
    if(~clk) master <= d;
  end

  // Slave latch (positive level sensitive)
  always @(clk or master) begin
    if(clk) slave <= master;
  end

  assign q = slave;
endmodule

