template:
module seq_det_mealy(input clk, rst, in, output reg out);
  reg [1:0] state, next_state;
  parameter S0=2'b00, S1=2'b01, S2=2'b10;

  // State transition
  always @(posedge clk or posedge rst) begin
    if(rst) state <= S0;
    else state <= next_state;
  end

  // Next state and output logic
  always @(*) begin
    case(state)
      S0: begin
        next_state = in ? S1 : S0;
        out = 1'b0;
      end
      S1: begin
        next_state = in ? S1 : S2;
        out = 1'b0;
      end
      S2: begin
        next_state = in ? S1 : S0;
        out = in ? 1'b1 : 1'b0;
      end
      default: begin
        next_state = S0;
        out = 1'b0;
      end
    endcase
  end
endmodule

